<script setup lang="ts">
	import type { AdminStats, FundingAccount } from '~/utils/interfaces/Funding';
	import { adminMoney, fundingTotals } from '~/utils/admin-ui';
	const stats = ref<AdminStats | null>(null);
	const funding = ref<FundingAccount[]>([]);
	const loading = ref(true);
	const error = ref('');
	const updated = ref('');
	const load = async () => {
		loading.value = true; error.value = '';
		try { const result = await Promise.all([statsService.admin(), fundingService.list()]); stats.value = result[0]; funding.value = result[1]; updated.value = new Date().toLocaleTimeString(); }
		catch { error.value = 'Unable to refresh the overview. Please try again.'; }
		finally { loading.value = false; }
	};
	const totals = computed(() => fundingTotals(funding.value));
	onMounted(load);
</script>
<template><div><AppPageHeader title="Workspace overview" description="A clear view of users, activity, and operational next steps."><button type="button" class="btn btn-light" :disabled="loading" @click="load">Refresh</button><NuxtLink to="/admin/top-up" class="btn btn-primary">Credit user</NuxtLink></AppPageHeader><AppLoadState :loading="loading && !stats" :error="error" :empty="!stats" title="Overview unavailable" @retry="load"><template v-if="stats"><p class="text-gray-600 fs-8 mb-5" aria-live="polite">Last refreshed {{ updated }}{{ loading ? ' · Refreshing…' : '' }}</p><div class="admin-metrics mb-7"><section v-for="item in [{ label: 'Total users', value: stats.users.total, note: `${stats.users.active} active` }, { label: 'Transactions', value: stats.transactions.total, note: 'Recorded activity' }, { label: 'Pending transactions', value: stats.transactions.pending, note: 'Awaiting or processing' }, { label: 'Failed transactions', value: stats.transactions.failed, note: 'Review individual records' }]" :key="item.label" class="card border"><div class="card-body p-6"><h2 class="fs-7 text-gray-600 mb-4">{{ item.label }}</h2><strong class="fs-2x text-gray-900">{{ item.value }}</strong><p class="text-gray-600 fs-8 mt-3 mb-0">{{ item.note }}</p></div></section></div><div class="admin-grid"><section class="card border"><div class="card-header align-items-center"><h2 class="card-title fs-4">Recent transactions</h2></div><div class="card-body"><p v-if="!stats.recentTransactions.length" class="text-gray-600">No recorded transactions yet.</p><NuxtLink v-for="tx in stats.recentTransactions" :key="String(tx.id)" :to="`/admin/transaction/${tx.id}`" class="admin-row d-flex align-items-center gap-4 py-5 border-bottom"><span class="symbol symbol-40px"><span class="symbol-label bg-light-primary"><i class="ki-outline ki-arrow-right-left text-primary fs-2" aria-hidden="true"></i></span></span><span class="flex-grow-1 admin-identity"><strong class="d-block text-gray-900 text-break">{{ tx.senderName || 'Account transaction' }}</strong><span class="text-gray-600 fs-8">{{ tx.type }} · {{ tx.status }}</span></span><span class="text-end"><strong class="d-block text-gray-900">{{ adminMoney(tx.amount) }}</strong><small class="text-gray-600">Account units</small></span></NuxtLink><p class="text-gray-600 fs-8 mt-5 mb-0">Amounts are recorded account units. Open a transaction to review its source account; totals across currencies are not combined.</p></div></section><div class="d-grid gap-7"><section class="card border"><div class="card-header align-items-center"><h2 class="card-title fs-4">Active funding balances</h2><NuxtLink to="/admin/funding" class="fs-7 fw-bold">Manage</NuxtLink></div><div class="card-body"><p v-if="!totals.length" class="text-gray-600">No active funding accounts.</p><div v-for="[code, amount] in totals" :key="code" class="d-flex justify-content-between gap-4 py-3"><span class="text-gray-600">{{ code }}</span><strong>{{ adminMoney(amount) }}</strong></div><p class="text-gray-600 fs-8 mt-4 mb-0">Tracked funding balances, not customer liabilities.</p></div></section><section class="card border"><div class="card-header align-items-center"><h2 class="card-title fs-4">Recently joined</h2><NuxtLink to="/admin/users" class="fs-7 fw-bold">All users</NuxtLink></div><div class="card-body"><p v-if="!stats.recentUsers.length" class="text-gray-600">No users yet.</p><NuxtLink v-for="person in stats.recentUsers" :key="person.id" :to="`/admin/users/${person.id}`" class="d-flex align-items-center gap-4 py-4 border-bottom"><AppAvatar :name="person.name || ''" :email="person.email || ''" /><span class="admin-identity"><strong class="d-block text-gray-900 text-break">{{ person.name || person.email }}</strong><small class="text-gray-600 text-break">{{ person.email }}</small></span></NuxtLink></div></section></div></div></template></AppLoadState></div></template>
